INSERT INTO "audios" ("id","title","description","image_path","audio_path","category_id","subcategory_id","duration","created_at","illustration_key","cover_color","is_published") VALUES (4,'Les Musiciens de Brême',NULL,'1789297701700-69f88861-db31-4473-9ed4-6f13d5e785f2-les-musiciens-de-breme.webp','1789293684636-bb996eac-75b5-40ad-829e-033a474360bb-les-musiciens-de-breme.m4a',1,6,165,'2026-09-13 10:01:29.631568+00','coq--s1-r4-c2',NULL,1) ON CONFLICT(id) DO UPDATE SET "title"=excluded."title","description"=excluded."description","image_path"=excluded."image_path","audio_path"=excluded."audio_path","category_id"=excluded."category_id","subcategory_id"=excluded."subcategory_id","duration"=excluded."duration","created_at"=excluded."created_at","illustration_key"=excluded."illustration_key","cover_color"=excluded."cover_color","is_published"=excluded."is_published";
