INSERT INTO "articles" ("id","title","excerpt","content","category","cover_path","published","published_at","created_at") VALUES (3,'Les questions des enfants','Voici une liste non exhaustive des questions posées par les enfants et les adolescents','<p><br></p><p><strong>Le cosmos et l''univers</strong></p><ol><li>Comment l''univers a-t-il commencé ?</li><li>Qu''y avait-il avant le Big Bang ?</li><li>L''univers a-t-il une fin, un bord ?</li><li>Qu''est-ce qu''un trou noir, et que se passe-t-il si on tombe dedans ?</li><li>Sommes-nous seuls dans l''univers ? Les extraterrestres existent-ils ?</li><li>Pourquoi le ciel est-il bleu le jour et noir la nuit ?</li><li>Combien y a-t-il d''étoiles dans le ciel ?</li><li>Pourquoi la Terre tourne-t-elle sur elle-même ?</li><li>Existe-t-il d''autres planètes habitables que la Terre ?</li><li>Que se passerait-il si le Soleil s''éteignait ?</li><li>Pourquoi voit-on parfois la Lune en plein jour ?</li><li>Existe-t-il des univers parallèles ?</li><li>Comment naissent et meurent les étoiles ?</li><li>Vivrons-nous un jour sur Mars ?</li><li>D''où vient l''eau présente sur Terre ?</li></ol><p><strong>La mort</strong> 16. Qu''est-ce que ça veut dire, être mort ? 17. Pourquoi est-ce qu''on meurt ? 18. Est-ce que moi aussi je vais mourir un jour ? 19. Est-ce que toi (papa, maman), tu vas mourir ? 20. Où va-t-on quand on meurt ? 21. Est-ce que ça fait mal de mourir ? 22. Pourquoi les gens qu''on aime doivent-ils mourir ? 23. Peut-on revoir une personne après sa mort ? 24. Pourquoi on enterre ou on brûle les morts ? 25. Est-ce que les animaux savent qu''ils vont mourir ? 26. Pourquoi a-t-on peur de la mort ? 27. Se souvient-on de sa vie après être mort ? 28. Qu''est-ce qui se passe dans le corps quand on meurt ? 29. Peut-on mourir de chagrin ?</p><p><strong>L''esprit, la conscience, les rêves</strong> 30. Pourquoi on rêve, et qu''est-ce que ça veut dire ? 31. Où va notre esprit quand on dort ? 32. Comment ça marche, une pensée, dans la tête ? 33. Est-ce que les animaux pensent comme nous ? 34. Qu''est-ce que l''âme, et où est-elle dans le corps ? 35. Pourquoi a-t-on parfois l''impression d''avoir déjà vécu un moment ? 36. Peut-on apprendre à contrôler ses rêves ? 37. Pourquoi fait-on des cauchemars ? 38. Peut-on un jour lire dans les pensées de quelqu''un ? 39. Qu''est-ce qui fait que je suis "moi" et pas quelqu''un d''autre ?</p><p><strong>Dieu et la religion</strong> 40. Qui est Dieu ? 41. Si Dieu a tout créé, qui a créé Dieu ? 42. Où habite Dieu ? 43. Pourquoi y a-t-il plusieurs religions ? 44. Est-ce que Dieu existe vraiment ? 45. À quoi ça sert de prier ? 46. Pourquoi certaines personnes ne croient en rien ? 47. Si Dieu est bon, pourquoi y a-t-il du mal sur Terre ? 48. C''est quoi le paradis, l''enfer ? 49. Pourquoi les religions ne sont-elles pas d''accord entre elles ? 50. Qu''est-ce qu''un miracle ? 51. Pourquoi fête-t-on Noël ou d''autres fêtes religieuses ?</p><p><strong>L''humanité, les origines et la société</strong> 52. D''où vient le tout premier homme ? 53. Pourquoi y a-t-il des guerres ? 54. Pourquoi certains sont pauvres et d''autres riches ? 55. Pourquoi y a-t-il des gens méchants ? 56. C''est quoi le racisme, et pourquoi ça existe encore ? 57. Pourquoi les gens ne sont-ils pas d''accord sur ce qui est juste ? 58. Est-ce qu''on descend vraiment du singe ? 59. Pourquoi y a-t-il des frontières entre les pays ? 60. L''humanité va-t-elle disparaître un jour ? 61. Pourquoi a-t-on inventé l''argent ? 62. Tout le monde a-t-il vraiment les mêmes droits dans le monde ?</p><p><strong>La santé et le corps</strong> 63. Pourquoi mon corps change-t-il à l''adolescence ? 64. Pourquoi j''ai des boutons ? 65. Pourquoi ma voix mue (pour les garçons) ? 66. Pourquoi j''ai mes règles, et est-ce normal d''avoir mal (pour les filles) ? 67. Pourquoi a-t-on besoin de dormir ? 68. Pourquoi suis-je fatigué même après une nuit de sommeil ? 69. C''est quoi le stress, et pourquoi ça donne mal au ventre ? 70. Pourquoi grandit-on par à-coups ? 71. Est-ce normal de ne pas aimer son corps ? 72. Pourquoi certaines personnes tombent-elles plus souvent malades ? 73. C''est quoi une maladie mentale ? 74. Pourquoi est-ce important de bien manger ?</p><p><strong>L''écologie et la planète</strong> 75. Pourquoi la planète se réchauffe-t-elle ? 76. Va-t-on réussir à sauver la planète à temps ? 77. Pourquoi les animaux disparaissent-ils ? 78. Pourquoi y a-t-il autant de plastique dans les océans ? 79. Qu''est-ce que je peux faire, moi, pour aider la planète ? 80. Pourquoi les adultes ne font-ils pas plus pour le climat ? 81. La Terre va-t-elle devenir inhabitable ? 82. Pourquoi coupe-t-on les forêts ? 83. C''est quoi l''effet de serre ? 84. Pourquoi y a-t-il de plus en plus de catastrophes naturelles ?</p><p><strong>L''amour et les relations</strong> 85. C''est quoi, vraiment, l''amour ? 86. Comment sait-on qu''on est amoureux ? 87. Pourquoi le cœur bat-il plus vite quand on aime quelqu''un ? 88. Est-ce que l''amour dure toujours ? 89. Pourquoi les gens se séparent-ils ? 90. Comment savoir si quelqu''un m''aime ? 91. Pourquoi est-ce difficile de dire à quelqu''un qu''on l''aime ? 92. Peut-on aimer deux personnes en même temps ? 93. Pourquoi ça fait si mal d''être rejeté ? 94. Quelle est la différence entre l''amitié et l''amour ?</p><p><strong>Les étapes de la vie</strong> 95. Comment on fait les bébés ? 96. Pourquoi devient-on adulte un jour ? 97. C''est quoi être vieux, ça fait quoi de vieillir ? 98. Pourquoi le temps semble passer plus vite en grandissant ? 99. Qu''est-ce que je vais devenir plus tard ? 100. Pourquoi faut-il choisir un métier ? 101. Reste-t-on la même personne toute sa vie ? 102. Pourquoi les enfants doivent-ils obéir aux adultes ? 103. Qu''est-ce que ça veut dire, être responsable ? 104. Pourquoi a-t-on besoin des autres pour être heureux ?</p><p>Excellente démarche ! Voici maintenant un large complément, avec des thèmes entièrement nouveaux et des questions oubliées dans les catégories précédentes.</p><p><br></p><p>**Le cosmos (oublis)**</p><p>1. Comment le temps a-t-il commencé ? Y a-t-il eu un "avant" le temps ?</p><p>2. L''univers est-il infini, et si oui, qu''est-ce qui est "après" ?</p><p>3. Pourquoi les planètes sont-elles rondes ?</p><p>4. Comment les satellites font-ils pour ne pas tomber sur Terre ?</p><p>5. Y a-t-il déjà eu des gens dans le Big Bang ?</p><p>6. Qu''est-ce qu''une année-lumière concrètement ?</p><p>7. Pourquoi fait-il si froid dans l''espace alors que le Soleil brûle ?</p><p>8. Qu''est-ce qu''une galaxie et combien en existe-t-il ?</p><p>9. Peut-on voyager dans le temps un jour ?</p><p><br></p><p>**La mort (oublis)**</p><p>10. Qu''est-ce qu''il se passe après l''enterrement, sous la terre ?</p><p>11. Les personnes mortes nous entendent-elles encore ?</p><p>12. Pourquoi on pleure quand quelqu''un meurt ?</p><p>13. Est-ce qu''on se retrouve tous après la mort ?</p><p>14. Pourquoi certains meurent jeunes et d''autres très vieux ?</p><p>15. Peut-on mourir de peur ?</p><p><br></p><p>**L''esprit et le cerveau (oublis)**</p><p>16. Pourquoi a-t-on parfois honte sans raison précise ?</p><p>17. Pourquoi certaines musiques nous donnent envie de pleurer ?</p><p>18. Pourquoi rit-on, à quoi ça sert le rire ?</p><p>19. Peut-on avoir plusieurs personnalités dans sa tête ?</p><p>20. Comment sait-on que l''on n''est pas en train de rêver en ce moment ?</p><p>21. Pourquoi certains ont-ils peur du noir ?</p><p><br></p><p>**Dieu et la religion (oublis)**</p><p>22. Si on ne croit pas en Dieu, va-t-on quand même au paradis ?</p><p>23. Les animaux ont-ils une âme ?</p><p>24. Dieu a-t-il créé le diable ?</p><p>25. Pourquoi certains font la guerre au nom de Dieu ?</p><p>26. La religion peut-elle être dangereuse ?</p><p><br></p><p>**L''humanité et la société (oublis)**</p><p>27. Pourquoi y a-t-il des gens qui dorment dans la rue ?</p><p>28. Pourquoi les hommes politiques ne règlent-ils pas tous les problèmes ?</p><p>29. Pourquoi l''histoire se répète-t-elle toujours ?</p><p>30. Pourquoi a-t-on inventé les armes ?</p><p>31. C''est quoi la démocratie, et est-ce que ça marche vraiment ?</p><p>32. Pourquoi certains pays sont-ils riches et d''autres pauvres ?</p><p><br></p><p>**La santé (oublis)**</p><p>33. Pourquoi les émotions font-elles mal physiquement (le cœur serré, les larmes) ?</p><p>34. Pourquoi grossit-on ou maigrit-on sans forcément le vouloir ?</p><p>35. Pourquoi a-t-on des maladies incurables si la médecine progresse ?</p><p>36. C''est quoi la dépression, et est-ce que ça guérit ?</p><p>37. Pourquoi certains se font du mal à eux-mêmes ?</p><p>38. Pourquoi a-t-on des phobies irrationnelles ?</p><p><br></p><p>**L''écologie (oublis)**</p><p>39. Pourquoi faut-il boycotter certains produits comme l''huile de palme ?</p><p>40. C''est quoi une espèce en voie de disparition, et peut-on la sauver ?</p><p>41. Y a-t-il vraiment un "point de non-retour" pour la planète ?</p><p>42. Pourquoi certains adultes ne croient pas au réchauffement climatique ?</p><p>43. L''eau va-t-elle manquer un jour sur Terre ?</p><p><br></p><p>**L''amour (oublis)**</p><p>44. Comment surmonter un chagrin d''amour ?</p><p>45. Est-ce normal d''être jaloux quand on aime quelqu''un ?</p><p>46. L''amour à distance, est-ce que ça marche vraiment ?</p><p>47. Peut-on aimer quelqu''un sans se l''avouer longtemps ?</p><p>48. Pourquoi certains couples se font du mal tout en restant ensemble ?</p><p><br></p><p>---</p><p><br></p><p>## THÈMES ENTIÈREMENT NOUVEAUX</p><p><br></p><p>**L''identité et la place dans le monde**</p><p>49. Qui suis-je vraiment ?</p><p>50. Suis-je la même personne qu''avant, ou est-ce que je change chaque jour ?</p><p>51. Pourquoi est-ce qu''on me dit de "trouver ma voie" alors que je ne sais pas ce que je veux ?</p><p>52. Pourquoi me sent-on différent des autres parfois, comme si on n''était pas à sa place ?</p><p>53. Pourquoi a-t-on peur du regard des autres ?</p><p>54. Qu''est-ce que l''identité : est-ce notre prénom, notre corps, notre façon de penser ?</p><p>55. Peut-on choisir qui on est, ou est-ce qu''on le devient sans le décider ?</p><p><br></p><p>**Le bonheur, le sens de la vie**</p><p>56. C''est quoi le bonheur, vraiment ?</p><p>57. Peut-on être heureux tout le temps ?</p><p>58. Pourquoi existe-t-on — quel est le sens de la vie ?</p><p>59. J''étais où avant de naître ?</p><p>60. Est-ce que la vie a un sens, ou est-ce qu''on lui en donne un ?</p><p>61. Peut-on trouver le bonheur seul, sans les autres ?</p><p>62. Pourquoi certaines choses nous rendent heureux et d''autres non, même si on les voulait fort ?</p><p><br></p><p>**Le bien, le mal, la morale**</p><p>63. Peut-on naître méchant, ou le devient-on ?</p><p>64. Est-ce qu''il y a des actes vraiment mauvais en toutes circonstances ?</p><p>65. Pourquoi mentir est-il mal si parfois ça protège les gens ?</p><p>66. Est-ce qu''on a le droit de se venger ?</p><p>67. Pourquoi certaines personnes font le mal tout en croyant bien faire ?</p><p>68. Peut-on être à la fois bon et méchant ?</p><p>69. C''est quoi la conscience, cette petite voix dans la tête ?</p><p><br></p><p>**La liberté, les règles, l''autorité**</p><p>70. Pourquoi faut-il obéir à des lois qu''on n''a pas choisies ?</p><p>71. Est-on vraiment libre si on ne peut pas faire tout ce qu''on veut ?</p><p>72. Pourquoi les adultes ont-ils plus de droits que les enfants ?</p><p>73. Pourquoi c''est toujours les adultes qui décident ?</p><p>74. Faut-il toujours respecter une règle injuste ?</p><p>75. Peut-on être libre en société ?</p><p><br></p><p>**Les animaux et le vivant**</p><p>76. Les animaux ressentent-ils de la douleur comme nous ?</p><p>77. Les animaux ont-ils des sentiments, aiment-ils vraiment leurs maîtres ?</p><p>78. Pourquoi mange-t-on des animaux si on les aime ?</p><p>79. Est-ce mal de tuer un animal pour se nourrir ?</p><p>80. Pourquoi certaines espèces existent-elles depuis des millions d''années et d''autres disparaissent vite ?</p><p>81. Les plantes sont-elles vivantes au sens où on l''est ?</p><p><br></p><p>**L''amitié et les autres**</p><p>82. C''est quoi une vraie amitié ?</p><p>83. Pourquoi certaines amitiés s''arrêtent-elles ?</p><p>84. Comment savoir si quelqu''un est vraiment mon ami ou fait semblant ?</p><p>85. Pourquoi est-ce si difficile de s''excuser ?</p><p>86. Pourquoi a-t-on besoin d''appartenir à un groupe ?</p><p>87. Peut-on être ami avec quelqu''un de très différent de soi ?</p><p><br></p><p>**La violence, la guerre, l''injustice**</p><p>88. Pourquoi y a-t-il des gens qui frappent ceux qu''ils aiment ?</p><p>89. Pourquoi le harcèlement existe-t-il à l''école ?</p><p>90. Pourquoi certains enfants souffrent-ils de la faim dans le monde ?</p><p>91. Pourquoi certains pays ont-ils des bombes nucléaires si c''est interdit de s''en servir ?</p><p>92. C''est quoi la justice, et est-ce qu''elle est vraiment juste pour tout le monde ?</p><p>93. Pourquoi les gens préfèrent-ils parfois regarder une injustice sans réagir ?</p><p><br></p><p>**L''argent et la réussite**</p><p>94. Pourquoi l''argent est-il si important pour les adultes ?</p><p>95. Peut-on être heureux sans argent ?</p><p>96. Pourquoi certains travaillent dur et restent pauvres, alors que d''autres sont riches sans travailler ?</p><p>97. À quoi ça sert d''aller à l''école si on ne sait pas encore ce qu''on veut faire ?</p><p>98. La réussite, c''est quoi — avoir de l''argent, être connu, être heureux ?</p><p><br></p><p>**Le temps, l''infini, l''existence**</p><p>99. C''est quoi le temps ? Pourquoi ne peut-on pas revenir en arrière ?</p><p>100. Pourquoi le temps semble-t-il passer lentement quand on s''ennuie et vite quand on est heureux ?</p><p>101. Qu''est-ce que l''infini — est-ce qu''on peut vraiment le comprendre ?</p><p>102. Y a-t-il un destin, ou est-ce qu''on écrit sa propre vie ?</p><p>103. Si tout finit par mourir un jour, à quoi ça sert de construire quelque chose ?</p><p><br></p><p>**Les technologies, les réseaux sociaux, l''IA**</p><p>104. Est-ce que les machines peuvent vraiment penser comme nous ?</p><p>105. Les réseaux sociaux sont-ils bons ou mauvais pour les jeunes ?</p><p>106. Pourquoi a-t-on autant besoin de "likes" pour se sentir bien ?</p><p>107. Les jeux vidéo peuvent-ils rendre violent ?</p><p>108. Une intelligence artificielle peut-elle avoir des émotions un jour ?</p><p>109. Si une machine fait tout mieux que l''humain, à quoi servirons-nous ?</p><p>110. Internet nous rend-il plus intelligents ou plus paresseux ?</p><p><br></p><p>**La beauté, l''art, la création**</p><p>111. Pourquoi la beauté n''est-elle pas la même pour tout le monde ?</p><p>112. À quoi sert l''art si ça ne nourrit pas les gens ?</p><p>113. Peut-on apprendre à être créatif, ou c''est un don ?</p><p>114. Pourquoi certaines œuvres font-elles pleurer sans qu''on sache pourquoi ?</p><p>115. Est-ce que tout le monde peut être artiste ?</p><p><br></p><p>**La naissance, les origines, la famille**</p><p>116. Comment on fait les bébés (posée à tout âge sous des formes différentes) ?</p><p>117. Pourquoi est-ce que je ressemble à mes parents dans certains caractères ?</p><p>118. Est-ce qu''on choisit sa famille, ou est-ce qu''on est condamné à celle qu''on a ?</p><p>119. Peut-on aimer ses parents même quand ils font des erreurs ?</p><p>120. Qu''est-ce qui fait qu''une famille est une "vraie" famille ?</p><p>.</p>','Admin','covers/1782111993541-les-questions-des-enfants.jpg',1,'2026-06-22 07:06:52.749+00','2026-06-22 07:06:43.523371+00') ON CONFLICT(id) DO UPDATE SET "title"=excluded."title","excerpt"=excluded."excerpt","content"=excluded."content","category"=excluded."category","cover_path"=excluded."cover_path","published"=excluded."published","published_at"=excluded."published_at","created_at"=excluded."created_at";
INSERT INTO "articles" ("id","title","excerpt","content","category","cover_path","published","published_at","created_at") VALUES (4,'Le Hack du Sablier : et si tu n''étais pas ce que tu crois ? ⏳','Découvrez la Science du Sablier, une vision fascinante de la conscience, du temps et de l''observation intérieure inspirée des Mystères d''Isis et des traditions spirituelles anciennes.','<h1>Le Hack du Sablier : et si tu n''étais pas ce que tu crois ? ⏳</h1><p>As-tu déjà eu l''impression que ta vie te glissait entre les doigts ?</p><p>Les jours passent. Les événements s''enchaînent. Tu cours après le bonheur, la réussite ou la paix intérieure, mais quelque chose semble toujours manquer.</p><p>Et si le problème n''était pas ta vie... mais la place depuis laquelle tu la regardes ?</p><p>Selon une vision ancienne inspirée des Mystères d''Isis, l''existence ressemble à un immense sablier.</p><h2>Le piège du temps</h2><p>Imagine deux mondes.</p><p>En haut, le domaine de l''éternité : ce qui ne change pas, ce qui existe au-delà du temps.</p><p>En bas, le monde que nous connaissons : la matière, le corps, les événements et les années qui passent.</p><p>Entre les deux, le sable s''écoule.</p><p>Ce sable représente ton expérience de la vie.</p><p>Le véritable piège apparaît lorsque la conscience s''identifie complètement à ce qui se passe dans la partie basse du sablier.</p><p>À ce moment-là, elle oublie ce qu''elle est et commence à croire :</p><blockquote>« Je suis seulement ce corps. Je suis seulement cette histoire. »</blockquote><p>Alors naissent la peur, le manque et la sensation permanente d''être limité.</p><h2>Pourquoi souffrons-nous ?</h2><p>La souffrance ne vient pas du monde.</p><p>Elle vient de notre identification au monde.</p><p>Lorsque tout ce que nous sommes dépend de notre apparence, de nos possessions ou du regard des autres, chaque changement devient une menace.</p><p>Nous passons alors notre temps à essayer de contrôler ce qui, par nature, ne peut être contrôlé.</p><p>Comme quelqu''un qui tenterait d''arrêter le sable de tomber.</p><h2>Le hack : devenir l''observateur</h2><p>La Science du Sablier propose une idée étonnamment simple.</p><p>Tu n''es pas obligé d''être le sable.</p><p>Tu peux devenir celui qui l''observe.</p><p>Prends un instant.</p><p>Il y a tes pensées.</p><p>Il y a tes émotions.</p><p>Il y a les événements de ta vie.</p><p>Mais il existe aussi quelque chose qui observe tout cela.</p><p>Une présence silencieuse qui était là dans tes moments de joie comme dans tes périodes les plus difficiles.</p><p>Plus ton attention se tourne vers cet observateur, moins tu es emporté par le courant.</p><p>Les problèmes ne disparaissent pas.</p><p>Mais ils cessent de définir qui tu es.</p><h2>La véritable liberté</h2><p>Depuis toujours, nous essayons de contrôler le sable.</p><p>Nous voulons retenir le temps, éviter les pertes et sécuriser l''avenir.</p><p>Pourtant, le sablier continuera toujours de s''écouler.</p><p>Peut-être que la liberté n''a jamais consisté à arrêter le mouvement.</p><p>Peut-être qu''elle commence lorsque nous réalisons que nous ne sommes pas le sable.</p><p>Nous sommes celui qui le regarde tomber.</p><p>Et dans cet espace d''observation, il existe une paix que le temps ne peut pas emporter.</p><h1>⏳✨</h1>','Science','covers/1782121491434-le-hack-du-sablier-et-si-ta-vie-etait-un.png',1,'2026-06-22 09:44:57.778+00','2026-06-22 09:44:58.785576+00') ON CONFLICT(id) DO UPDATE SET "title"=excluded."title","excerpt"=excluded."excerpt","content"=excluded."content","category"=excluded."category","cover_path"=excluded."cover_path","published"=excluded."published","published_at"=excluded."published_at","created_at"=excluded."created_at";
